mapper.select:
SELECT CONCAT('ORD-', id) AS order_id, account_id, symbol, side, quantity, price, executed_price, status, idempotency_key, created_on, rejection_reason FROM orders WHERE account_id = #{accountId}
AND status = #{status}
AND created_on >= #{from}
AND created_on <= #{to}
ORDER BY created_on DESC

SELECT EXISTS(
    SELECT 1
    FROM orders
    WHERE idempotency_key = #{idempotencyKey}
)

mapper.update:
UPDATE orders
SET status = 'REJECTED',
    rejection_reason = #{rejectionReason},
    updated_on = #{updatedOn}
WHERE id = #{id}
  AND status = 'NEW'

mapper.select:
SELECT COALESCE(SUM(quantity), 0)
FROM orders
WHERE account_id = #{accountId}
  AND symbol = #{symbol}
  AND side = 'SELL'
  AND status = 'NEW'
